/**
 * @brief  I2S2 initialization for INMP441.
 *
 *         Mode     : Master receive, I2S Philips standard
 *         Data bits: 24-bit in 32-bit frame (DATALEN=24, CHLEN=32)
 *         MCLK     : disabled
 *         Clock    : derived from PLL3 (49.152 MHz) for exact 16 kHz
 *
 *         PLL3 configuration (set in SystemClock_Config or CubeMX):
 *           DIVM3=4, DIVN3=96, DIVP3=3 → 49.152 MHz
 *         I2S prescaler: DIV=24 → I2SCLK = 49.152 / (2×24) = 1.024 MHz
 *         BCK  = 1.024 MHz / (32 bits × 2 channels) = 16 000 Hz ✓
 */
static void MX_I2S2_Init(void)
{
    __HAL_RCC_SPI2_CLK_ENABLE();
    __HAL_RCC_GPIOB_CLK_ENABLE();

    /*
     * Configure I2S2 GPIO pins:
     *   PB12 – I2S2_WS   (AF5)
     *   PB13 – I2S2_CK   (AF5)
     *   PB15 – I2S2_SDI  (AF5)
     */
    GPIO_InitTypeDef GPIO_InitStruct = {0};
    GPIO_InitStruct.Pin       = GPIO_PIN_12 | GPIO_PIN_13 | GPIO_PIN_15;
    GPIO_InitStruct.Mode      = GPIO_MODE_AF_PP;
    GPIO_InitStruct.Pull      = GPIO_NOPULL;
    GPIO_InitStruct.Speed     = GPIO_SPEED_FREQ_MEDIUM;
    GPIO_InitStruct.Alternate = GPIO_AF5_SPI2;
    HAL_GPIO_Init(GPIOB, &GPIO_InitStruct);

    hi2s2.Instance          = SPI2;
    hi2s2.Init.Mode         = I2S_MODE_MASTER_RX;
    hi2s2.Init.Standard     = I2S_STANDARD_PHILIPS;
    hi2s2.Init.DataFormat   = I2S_DATAFORMAT_24B;
    hi2s2.Init.MCLKOutput   = I2S_MCLKOUTPUT_DISABLE;
    hi2s2.Init.AudioFreq    = I2S_AUDIOFREQ_16K;
    hi2s2.Init.CPOL         = I2S_CPOL_LOW;
    hi2s2.Init.FirstBit     = I2S_FIRSTBIT_MSB;
    hi2s2.Init.WSInversion  = I2S_WS_INVERSION_DISABLE;
    hi2s2.Init.IOSwap       = I2S_IO_SWAP_DISABLE;
    hi2s2.Init.Data24BitAlignment = I2S_DATA_24BIT_ALIGNMENT_RIGHT;
    hi2s2.Init.FifoThreshold      = I2S_FIFO_THRESHOLD_01DATA;
    hi2s2.Init.MasterKeepIOState  = I2S_MASTER_KEEP_IO_STATE_DISABLE;
    hi2s2.Init.SlaveExtendedMode  = I2S_SLAVE_EXTEND_DISABLE;
    HAL_I2S_Init(&hi2s2);
}

